From f201f6eb5e0eb9a8a2c57c39b1f997be2e918129 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:42:44 +0100
Subject: [PATCH] applets/digitalclock: allow copying any date from the
 calendar

The Copy to Clipboard menu only offered today's date, so there was no way
to copy another day shown in the calendar. Right-clicking or long-pressing
a day now selects it and opens a menu to copy it in a few date formats.

BUG: 330531
---
 applets/digital-clock/CalendarView.qml   | 40 ++++++++++++++++++++++++
 components/calendar/qml/DaysCalendar.qml | 12 +++++++
 components/calendar/qml/MonthView.qml    | 10 ++++++
 3 files changed, 62 insertions(+)

diff --git a/applets/digital-clock/CalendarView.qml b/applets/digital-clock/CalendarView.qml
index 48d5dcccb7..b550a75dcf 100644
--- a/applets/digital-clock/CalendarView.qml
+++ b/applets/digital-clock/CalendarView.qml
@@ -21,6 +21,7 @@ import org.kde.plasma.private.digitalclock
 import org.kde.config as KConfig
 import org.kde.kcmutils as KCMUtils
 import org.kde.kirigami as Kirigami
+import org.kde.kquickcontrolsaddons as KQuickControlsAddons
 import org.kde.plasma.clock

 // Top-level layout containing:
@@ -648,6 +649,45 @@ PlasmaExtras.Representation {
             KeyNavigation.left: KeyNavigation.tab
             KeyNavigation.tab: addEventButton.visible ? addEventButton : addEventButton.KeyNavigation.down
             Keys.onUpPressed: viewHeader.previousButton.forceActiveFocus(Qt.BacktabFocusReason);
+
+            onDateContextMenuRequested: (date, item, position) => {
+                dateContextMenu.date = date;
+                dateContextMenu.visualParent = item;
+                dateContextMenu.open(position.x, position.y);
+            }
+        }
+
+        PlasmaExtras.Menu {
+            id: dateContextMenu
+
+            property date date
+            // e.g. 4/28/22
+            readonly property string shortDate: date.toLocaleDateString(Qt.locale(), Locale.ShortFormat)
+            // e.g. Thursday, April 28, 2022
+            readonly property string longDate: date.toLocaleDateString(Qt.locale(), Locale.LongFormat)
+            // e.g. 2022-04-28
+            readonly property string isoDate: Qt.formatDate(date, Qt.ISODate)
+
+            PlasmaExtras.MenuItem {
+                section: true
+                text: i18n("Copy to Clipboard")
+            }
+            PlasmaExtras.MenuItem {
+                text: dateContextMenu.shortDate
+                onClicked: clipboard.content = dateContextMenu.shortDate
+            }
+            PlasmaExtras.MenuItem {
+                text: dateContextMenu.longDate
+                onClicked: clipboard.content = dateContextMenu.longDate
+            }
+            PlasmaExtras.MenuItem {
+                text: dateContextMenu.isoDate
+                onClicked: clipboard.content = dateContextMenu.isoDate
+            }
+        }
+
+        KQuickControlsAddons.Clipboard {
+            id: clipboard
         }
     }
 }
diff --git a/components/calendar/qml/DaysCalendar.qml b/components/calendar/qml/DaysCalendar.qml
