                 width: daysCalendar.cellWidth
@@ -195,6 +197,16 @@ Item {
                 onClicked: {
                     daysCalendar.activated(index, model, this)
                 }
+                onPressAndHold: {
+                    daysCalendar.contextMenuRequested(index, model, this, Qt.point(pressX, pressY))
